def supersede_phase23_human_mfa(apps, schema_editor):
    """Make the Microsoft Authenticator design authoritative without deleting legacy helpers."""
    Policy = apps.get_model('core', 'DeviceLoginMfaPolicy')
    for policy in Policy.objects.all():
        policy.mechanism = 'RADIUS_TOTP'
        policy.central_aaa_state = 'PLANNED'
        policy.radius_secret_ref = f"runtime://human-mfa/radius/{policy.device_name.lower()}"
        policy.radius_source_interface = 'Management0' if policy.device_name == 'R5' else 'Vlan200'
        policy.automation_exempt = True
        policy.candidate_digest = ''
        policy.last_verified_at = None
        policy.last_verification_result = ''
        if policy.device_name in LINUX:
            policy.enforcement_state = 'BLOCKED'
            policy.blocked_reason = 'ROOT_ONLY_ACCOUNT_AND_PAM_NOT_IMPLEMENTED'
        elif policy.device_name == 'R5':
            policy.enforcement_state = 'BLOCKED'
            policy.blocked_reason = 'OUTSIDE_MANAGED_SCOPE'
        else:
            policy.enforcement_state = 'PLANNED'
            policy.blocked_reason = ''
        policy.save()


